{"command":"cat > src/cli.js <<'EOF'
import fs from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

const cps = Array.from(fs.readFileSync(0, 'utf8'))
const n = cps.length
const lines = new Array(n + 1)
const cols = new Array(n + 1)
{
  let l = 1, c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l; cols[i] = c
    if (cps[i] === '\n') { l++; c = 1 } else if (cps[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l; cols[n] = c
}

class ScanError extends Error {
  constructor(i, reason) { super(reason); this.i = i }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isLetter = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isIdent = (c) => isLetter(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scanNumber(start) {
  let i = start
  const fail = () => {
    while (isIdent(cps[i])) i++
    throw new ScanError(start, 'invalid number ' + cps.slice(start, i).join(''))
  }
  // digit run with single underscores between digits
  const run = (pred) => {
    i++
    for (;;) {
      if (pred(cps[i])) i++
      else if (cps[i] === '_' && pred(cps[i + 1])) i += 2
      else break
    }
  }
  const p = cps[start + 1]
  if (cps[start] === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
    const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? (c) => c === '0' || c === '1' : (c) => c !== undefined && c >= '0' && c <= '7'
    i = start + 2
    if (!pred(cps[i])) fail()
    run(pred)
  } else {
    run(isDigit)
    if (cps[i] === '.' && isDigit(cps[i + 1])) { i++; run(isDigit) }
    if (cps[i] === 'e' || cps[i] === 'E') {
      if (isDigit(cps[i + 1])) { i++; run(isDigit) }
      else if ((cps[i + 1] === '+' || cps[i + 1] === '-') && isDigit(cps[i + 2])) { i += 2; run(isDigit) }
    }
  }
  if (isIdent(cps[i])) fail()
  return i
}

function scanString(start, q) {
  // q is index of opening quote
  let i = q + 1
  let value = ''
  for (;;) {
    if (i >= n) throw new ScanError(start, 'unterminated string')
    const c = cps[i]
    if (c === '"') return [value, i + 1]
    if (c === '\n') throw new ScanError(i, 'newline in string')
    if (c !== '\\') { value += c; i++; continue }
    const e = cps[i + 1]
    if (e === undefined) throw new ScanError(start, 'unterminated string')
    const bad = () => new ScanError(i, 'invalid escape \\' + e)
    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
    if (Object.hasOwn(simple, e)) { value += simple[e]; i += 2 } else if (e === 'x') {
      if (!isHex(cps[i + 2]) || !isHex(cps[i + 3])) throw bad()
      value += String.fromCodePoint(parseInt(cps[i + 2] + cps[i + 3], 16)); i += 4
    } else if (e === 'u') {
      if (cps[i + 2] !== '{') throw bad()
      let j = i + 3
      let h = ''
      while (isHex(cps[j])) h += cps[j++]
      if (h === '' || cps[j] !== '}') throw bad()
      const v = parseInt(h, 16)
      if (v > 0x10ffff) throw bad()
      value += String.fromCodePoint(v); i = j + 1
    } else throw bad()
  }
}

function scan() {
  const out = []
  let i = 0
  while (i < n) {
    const c = cps[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { i++; continue }
    if (c === '/' && cps[i + 1] === '/') {
      while (i < n && cps[i] !== '\n') i++
      continue
    }
    if (c === '/' && cps[i + 1] === '*') {
      const s = i
      let depth = 1
      i += 2
      while (depth > 0) {
        if (i >= n) throw new ScanError(s, 'unterminated block comment')
        if (cps[i] === '/' && cps[i + 1] === '*') { depth++; i += 2 } else if (cps[i] === '*' && cps[i + 1] === '/') { depth--; i += 2 } else i++
      }
      continue
    }
    const start = i
    if (c === 'r' && cps[i + 1] === '"') {
      let j = i + 2
      while (j < n && cps[j] !== '"') j++
      if (j >= n) throw new ScanError(start, 'unterminated string')
      out.push({ i: start, kind: 'rawstring', body: JSON.stringify(cps.slice(i + 2, j).join('')) })
      i = j + 1
    } else if (isLetter(c)) {
      while (isIdent(cps[i])) i++
      const t = cps.slice(start, i).join('')
      out.push({ i: start, kind: KEYWORDS.has(t) ? 'keyword' : 'ident', body: t })
    } else if (isDigit(c)) {
      i = scanNumber(start)
      out.push({ i: start, kind: 'number', body: cps.slice(start, i).join('') })
    } else if (c === '"') {
      const [v, end] = scanString(start, i)
      out.push({ i: start, kind: 'string', body: JSON.stringify(v) })
      i = end
    } else if (PUNCT2.has(c + (cps[i + 1] ?? ''))) {
      out.push({ i: start, kind: 'punct', body: c + cps[i + 1] }); i += 2
    } else if (PUNCT1.has(c)) {
      out.push({ i: start, kind: 'punct', body: c }); i++
    } else throw new ScanError(i, 'unexpected character ' + c)
  }
  return out
}

let toks
try {
  toks = scan()
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${lines[e.i]}:${cols[e.i]}: ${e.message}\n`)
  process.exit(2)
}
let text = ''
if (mode === 'tokens') {
  for (const t of toks) text += `${lines[t.i]}:${cols[t.i]} ${t.kind} ${t.body}\n`
} else {
  const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
  for (const t of toks) counts[t.kind]++
  for (const k of Object.keys(counts)) text += `${k} ${counts[k]}\n`
  text += `total ${toks.length}\n`
}
process.stdout.write(text)
EOF
