{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function changesOf(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const all = [
    ...changesOf(base, mine).map(c => ({ ...c, side: 0 })),
    ...changesOf(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)

  const out = []
  let conflict = false
  const emit = (kind, resolved, parts) => {
    if (mode === 'regions') {
      if (kind === 'conflict') out.push(`conflict mine=${parts[0].length} base=${parts[1].length} theirs=${parts[2].length}`)
      else out.push(`${kind} ${resolved.length}`)
    } else if (kind === 'conflict') {
      out.push('<<<<<<< mine', ...parts[0])
      if (mode === 'merge') out.push('||||||| base', ...parts[1])
      out.push('=======', ...parts[2], '>>>>>>> theirs')
    } else out.push(...resolved)
  }

  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) {
      const s = base.slice(pos, rs)
      emit('stable', s, null)
    }
    pos = re
    const baseLines = base.slice(rs, re)
    const sideLines = [mine, theirs].map((doc, sd) => {
      const cs = group.filter(c => c.side === sd)
      if (!cs.length) return baseLines
      const first = cs[0], last = cs[cs.length - 1]
      let maxBe = cs[0]
      for (const c of cs) if (c.be > maxBe.be) maxBe = c
      const start = first.ss - (first.bs - rs)
      const end = last.se + (re - maxBe.be)
      return doc.slice(start, end)
    })
    const [m, t] = sideLines
    if (same(m, t)) emit('both', m, null)
    else if (same(m, baseLines)) emit('theirs', t, null)
    else if (same(t, baseLines)) emit('mine', m, null)
    else {
      conflict = true
      emit('conflict', null, [m, baseLines, t])
