import { readFileSync } from 'node:fs'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const fail = (msg, code = 2) => {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
let mode = args[0]
let workers = 0
if (!((mode === 'waves' || mode === 'explain') && args.length === 1) && !(mode === 'pack' && args.length === 2)) fail(USAGE)
if (mode === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
}

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const uses = []
const NAME = /^[A-Za-z0-9_.-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const x of w.slice(1)) uses.push(x)
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of uses) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort(cmp)
const dl = new Map(names.map((k) => [k, [...(deps.get(k) || [])].sort(cmp)]))

// cycle detection (iterative DFS)
const state = new Map()
for (const root of names) {
  if (state.has(root)) continue
  const stack = [root]
  const idx = [0]
  state.set(root, 1)
  while (stack.length) {
    const top = stack[stack.length - 1]
    const list = dl.get(top)
    if (idx[idx.length - 1] >= list.length) {
      state.set(top, 2)
      stack.pop()
      idx.pop()
      continue
    }
    const d = list[idx[idx.length - 1]++]
    const s = state.get(d)
    if (s === 1) {
      const cyc = stack.slice(stack.indexOf(d))
      fail('error: cycle: ' + [...cyc, d].join(' -> '), 3)
    }
    if (!s) {
      state.set(d, 1)
      stack.push(d)
      idx.push(0)
    }
  }
}

// topological order: DFS post-order gives deps first
const order = []
{
  const seen = new Set()
  for (const root of names) {
    if (seen.has(root)) continue
    const stack = [root]
    const idx = [0]
    seen.add(root)
    while (stack.length) {
      const top = stack[stack.length - 1]
      const list = dl.get(top)
      if (idx[idx.length - 1] >= list.length) {
        order.push(top)
        stack.pop()
        idx.pop()
        continue
      }
      const d = list[idx[idx.length - 1]++]
      if (!seen.has(d)) {
