  for (const d of dl.get(k)) {
    s = Math.max(s, finish.get(d))
    dp = Math.max(dp, depth.get(d) + 1)
  }
  start.set(k, s)
  finish.set(k, s + cost.get(k))
  depth.set(k, dp)
  total = Math.max(total, s + cost.get(k))
}

const out = []
if (mode === 'waves') {
  const ws = []
