class ConfError extends Error {}
const fail = (m) => { throw new ConfError(m) }

const isWs = (c) => c === ' ' || c === '\t'
const isCom = (c) => c === '#' || c === ';'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

const newTable = () => ({ t: 'table', m: new Map(), header: false })

function step(tbl, path, key) {
  const p = path.concat([key])
  let child = tbl.m.get(key)
  if (child === undefined) {
    child = newTable()
    tbl.m.set(key, child)
  } else if (child.t === 'array' && child.aot) {
    child = child.items[child.items.length - 1]
  } else if (child.t !== 'table') {
    fail(`${p.join('.')} is not a table`)
  }
  return [child, p]
}

function assign(base, basePath, keys, value) {
  let tbl = base
  let path = basePath
  for (let i = 0; i < keys.length - 1; i++) [tbl, path] = step(tbl, path, keys[i])
  const last = keys[keys.length - 1]
  if (tbl.m.has(last)) fail(`key ${path.concat([last]).join('.')} is defined twice`)
  tbl.m.set(last, value)
}

class Parser {
  constructor(line) { this.s = line; this.i = 0 }
  peek() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { return this.i >= this.s.length || isCom(this.s[this.i]) }

  string() {
    const q = this.s[this.i++]
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const c = this.s[this.i++]
      if (c === q) return out
      if (q === "'" || c !== '\\') { out += c; continue }
      if (this.i >= this.s.length) fail('unterminated string')
      const e = this.s[this.i++]
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail(`invalid escape \\${e}`)
    }
  }

  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const keys = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        keys.push(this.name())
      } else { this.i = save; return keys }
    }
  }

  value(path) {
    this.ws()
    const c = this.peek()
    if (c === undefined || isCom(c) || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === 'true') return { t: 'boolean', v: true }
    if (tok === 'false') return { t: 'boolean', v: false }
    const I = '[+-]?\\d+(?:_\\d+)*'
    if (new RegExp(`^${I}$`).test(tok)) return { t: 'integer', v: Number(tok.replace(/_/g, '')) }
    if (new RegExp(`^${I}(?:\\.\\d+(?:_\\d+)*)?(?:[eE][+-]?\\d+(?:_\\d+)*)?$`).test(tok)) {
      return { t: 'float', v: Number(tok.replace(/_/g, '')) }
    }
    return fail(`invalid value ${tok}`)
  }

  array(path) {
    this.i++
    const items = []
    const node = { t: 'array', items, aot: false }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.peek() === ']') { this.i++; return node }
      items.push(this.value(path.slice(0, -1).concat([path[path.length - 1] + `[${items.length}]`])))
      this.ws()
      const c = this.peek()
      if (c === ',') { this.i++; continue }
      if (c === ']') { this.i++; return node }
      if (this.atEnd()) fail('unterminated array')
      fail('trailing text after a value')
    }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.peek() === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(path.concat(keys))
      assign(tbl, path, keys, v)
      this.ws()
      const c = this.peek()
      if (c === ',') { this.i++; continue }
      if (c === '}') { this.i++; return tbl }
      if (this.atEnd()) fail('unterminated inline table')
      fail('trailing text after a value')
    }
  }
}

function parse(text) {
  const root = newTable()
  let cur = root
  let curPath = []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let n = 0
  try {
    for (const line of lines) {
      n++
      const p = new Parser(line)
      p.ws()
      if (p.i >= line.length || isCom(p.peek())) continue
      if (p.peek() === '[') {
        const dbl = line[p.i + 1] === '['
        p.i += dbl ? 2 : 1
        p.ws()
        const keys = p.dotted()
        p.ws()
        for (let k = 0; k < (dbl ? 2 : 1); k++) {
          if (p.peek() !== ']') fail('unterminated table header')
          p.i++
        }
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        let tbl = root
        let path = []
        for (let k = 0; k < keys.length - 1; k++) [tbl, path] = step(tbl, path, keys[k])
        const last = keys[keys.length - 1]
        const full = path.concat([last])
        const ex = tbl.m.get(last)
        if (dbl) {
          if (ex === undefined) {
            const t = newTable()
            tbl.m.set(last, { t: 'array', items: [t], aot: true })
            cur = t
          } else if (ex.t === 'array' && ex.aot) {
            const t = newTable()
            ex.items.push(t)
            cur = t
          } else fail(`${full.join('.')} is not an array of tables`)
        } else {
          if (ex === undefined) {
            const t = newTable()
            t.header = true
            tbl.m.set(last, t)
            cur = t
          } else if (ex.t === 'table') {
            if (ex.header) fail(`table ${full.join('.')} is defined twice`)
            ex.header = true
            cur = ex
          } else fail(`${full.join('.')} is not a table`)
        }
        curPath = full
        continue
      }
      const keys = p.dotted()
      p.ws()
      if (p.peek() !== '=') fail('expected key = value')
      p.i++
      const v = p.value(curPath.concat(keys))
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    }
  } catch (e) {
    if (e instanceof ConfError) throw new ConfError(`line ${n}: ${e.message}`)
    throw e
  }
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function toJson(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (node.t === 'table') {
    const ks = sortedKeys(node)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(node.m.get(k), ind + 1)}`).join(',\n') + `\n${end}}`
  }
  if (node.t === 'array') {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + `\n${end}]`
  }
  return JSON.stringify(node.v)
}

function keyLines(node, path, out) {
  if (node.t === 'table') {
    for (const k of sortedKeys(node)) {
      const p = path === null ? k : `${path}.${k}`
      const c = node.m.get(k)
      out.push(`${p} ${c.t}`)
      keyLines(c, p, out)
    }
  } else if (node.t === 'array') {
    node.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${c.t}`)
      keyLines(c, p, out)
    })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
let doc
try {
  doc = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ConfError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
if (args[0] === 'json') process.stdout.write(toJson(doc, 0) + '\n')
else {
  const out = []
  keyLines(doc, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
"}

