    for (const v of votes.values()) if (min === null || v < min) min = v
    let tied = [...votes].filter(([, v]) => v === min).map(([c]) => c)
    for (let r = 0; r < rounds.length && tied.length > 1; ) {
      const vs = tied.map((c) => rounds[r].votes.get(c))
      let m = vs[0]
      for (const v of vs) if (v < m) m = v
      if (vs.every((v) => v === m)) { r++; continue }
      tied = tied.filter((c) => rounds[r].votes.get(c) === m)
      r = 0
    }
