    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.m.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
