  if (n.t === 'table') {
    for (const k of sortedKeys(n)) {
      const p = path === null ? k : `${path}.${k}`
      const c = n.m.get(k)
      out.push(`${p} ${c.t}`)
      keys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${c.t}`)
      keys(c, p, out)
    })
  }
