import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function num(field, text, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function parse(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  let n = 0
  for (const raw of lines) {
    n++
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (d === 'bucket' || d === 'window') {
        const isB = d === 'bucket'
        const arity = isB ? 5 : 4
        if (t.length !== arity) {
          throw new Fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        }
        if (lastTick !== null) throw new Fail('declarations must come before the first event')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        let p
        if (isB) {
          p = { kind: 'bucket', cap: num('capacity', t[2], 1), refill: num('refill', t[3], 0), per: num('per', t[4], 1) }
        } else {
          p = { kind: 'window', limit: num('limit', t[2], 0), span: num('span', t[3], 1) }
        }
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        p.name = t[1]
        policies.set(t[1], p)
      } else if (d === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (lastTick !== null) throw new Fail('declarations must come before the first event')
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        for (const name of t.slice(2)) {
          if (!policies.has(name)) throw new Fail(`unknown policy ${name}`)
        }
        routes.set(t[1], t.slice(2).map((x) => policies.get(x)))
      } else if (d === 'event') {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num('tick', t[1], 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push([tick, t[2]])
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${n}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function newState(p, tick) {
  return p.kind === 'bucket' ? { num: p.cap * p.per, last: tick } : { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const max = p.cap * p.per
    s.num += p.refill * (tick - s.last)
    if (s.num > max) s.num = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
}

function allows(p, s) {
  return p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
}

function record(p, s, tick) {
  if (p.kind === 'bucket') s.num -= p.per
  else s.ticks.push(tick)
}

let out = ''
try {
  const { routes, events } = parse(readFileSync(0, 'utf8'))
  const states = new Map()
  const counts = new Map()
  let ta = 0
  let td = 0
  for (const [tick, key] of events) {
    let best = null
    for (const prefix of routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    const list = best === null ? [] : routes.get(best)
    const sts = list.map((p) => {
      const id = p.name + '\0' + key
      if (!states.has(id)) states.set(id, newState(p, tick))
      const s = states.get(id)
      advance(p, s, tick)
      return s
    })
    let denied = null
    for (let i = 0; i < list.length; i++) {
      if (!allows(list[i], sts[i])) { denied = list[i].name; break }
    }
    if (denied === null) list.forEach((p, i) => record(p, sts[i], tick))
    const c = counts.get(key) || [0, 0]
    counts.set(key, c)
    if (denied === null) { c[0]++; ta++ } else { c[1]++; td++ }
    if (mode === 'replay') out += `${tick} ${key} ${denied === null ? 'allow' : 'deny ' + denied}\n`
  }
  if (mode === 'summary') {
    for (const k of [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      out += `${k} allowed=${counts.get(k)[0]} denied=${counts.get(k)[1]}\n`
    }
    out += `total allowed=${ta} denied=${td}\n`
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
EOF
